# Break My Fix finding 1, generated by Tracefix: Listener.port raises ValueError.
# Property (docstring): Blank (empty or whitespace-only) string returns self.default_port
# Quote: An unset (None) or blank value gives `self.default_port`.
# Run it with pytest: it fails for as long as the code breaks this property.

import copy

from gateway.listener import Listener


def test_break_my_fix_1() -> None:
    self_after = Listener()
    self = copy.deepcopy(self_after)
    raw = ''
    # The property applies to this input: isinstance(raw, str) and raw.strip() == ''
    result = self_after.port(raw=raw)
    assert result == (self.default_port)
